NODES = {
    2: (('push', 0), ('call', 0, 1)),
    3: (('push', 2), ('push', 0), ('call', 2, 0), ('call', 2, 1), ('call', 0, 1), ('over', 2, 0, 1)),
    4: (('push', 3), ('push', 2), ('push', 0), ('call', 3, 2), ('call', 3, 0), ('call', 3, 1), ('call', 2, 0), ('call', 2, 1), ('call', 0, 1), ('over', 3, 2, 0), ('over', 3, 2, 1), ('over', 3, 0, 1), ('over', 2, 0, 1)),
}
NODE_INDEX = {n: {nd: i for i, nd in enumerate(v)} for n, v in NODES.items()}
_EDGES = tuple((GRID[i] + GRID[i + 1]) / 2.0 for i in range(len(GRID) - 1))


def bucket(x_bb):
    """Index of the nearest GRID stack (ties go up); outside the grid: the end buckets."""
    i = 0
    for e in _EDGES:
        if x_bb < e:
            return i
        i += 1
    return i


def row_index(stacks_bb):
    """Grid point number of a stack vector (SB first), base len(GRID), last position fastest."""
    r = 0
    for x in stacks_bb:
        r = r * len(GRID) + bucket(x)
    return r


def lookup(n, kind, stacks_bb, node):
    """The 169-bit mask of `node` at the nearest grid point, or None (no table for n / kind / node)."""
    rows = ROWS.get((n, kind))
    ni = NODE_INDEX.get(n, {}).get(node)
    if rows is None or ni is None:
        return None
    p = (row_index(stacks_bb) * len(NODES[n]) + ni) * 4
    q = int(rows[p:p + 4], 16) * 43
    return int(MASKS[q:q + 43], 16)


